import rasterio
import numpy as np
import matplotlib.pyplot as plt

print("Generating Publication-Ready Figure 8: Pie Chart...")

# Load the classified map generated by the AI
class_path = r"C:\Users\SHIMELES_TADESSE\MR-EO-Ethiopia\outputs\landcover_classified.tif"

with rasterio.open(class_path) as src:
    classified = src.read(1)
    
# Count pixels for each class (0=Vegetation, 1=Urban, 2=Water)
unique, counts = np.unique(classified, return_counts=True)
class_counts = dict(zip(unique, counts))

# Extract counts for our 3 classes
veg_count = class_counts.get(0, 0)
urban_count = class_counts.get(1, 0)
water_count = class_counts.get(2, 0)

# Calculate percentages
total = veg_count + urban_count + water_count
sizes = [veg_count, urban_count, water_count]
labels = ['Vegetation', 'Urban / Bare Soil', 'Water Bodies']
colors = ['#2ca02c', '#7f7f7f', '#1f77b4'] # Green, Gray, Blue

# Filter out classes with 0 pixels (just in case)
filtered_labels = []
filtered_sizes = []
filtered_colors = []
for l, s, c in zip(labels, sizes, colors):
    if s > 0:
        filtered_labels.append(l)
        filtered_sizes.append(s)
        filtered_colors.append(c)

# Setup the figure
fig, ax = plt.subplots(figsize=(10, 8))

# Create the pie chart
wedges, texts, autotexts = ax.pie(
    filtered_sizes, 
    labels=filtered_labels, 
    colors=filtered_colors,
    autopct='%1.1f%%', 
    startangle=140, 
    textprops={'fontsize': 14, 'fontweight': 'bold'},
    wedgeprops={'edgecolor': 'black', 'linewidth': 1.5}, # Add black outlines to slices
    explode=(0.02, 0.02, 0.02) # Slightly pull the slices apart for a modern look
)

# Customize the percentage text color to be white or black depending on the slice color
for autotext in autotexts:
    autotext.set_color('white')

# Add Title
plt.title('Figure 8: AI Land Cover Distribution\n(Addis Ababa, Ethiopia)', 
          fontsize=18, fontweight='bold', pad=20)

# Add a subtle shadow for a 3D professional effect
ax.axis('equal') # Ensure pie is drawn as a circle
plt.tight_layout()

out_img = r"C:\Users\SHIMELES_TADESSE\MR-EO-Ethiopia\outputs\Figure_8_Publication_PieChart.png"
plt.savefig(out_img, dpi=300, bbox_inches='tight')
print(f"✅ Figure 8 successfully saved to: {out_img}")